import pyomo.environ as pyo

DATA = {
    "foods": ["Steak", "Rice", "Chicken", "Iceberg_Lettuce", "Almonds"],
    "nutrients": ["protein", "carbs", "calories"],
    "cost": {
        "Steak": 7,
        "Rice": 8,
        "Chicken": 2,
        "Iceberg_Lettuce": 8,
        "Almonds": 2,
    },
    "content": {
        "protein": {
            "Steak": 20,
            "Rice": 6,
            "Chicken": 17,
            "Iceberg_Lettuce": 1,
            "Almonds": 10,
        },
        "carbs": {
            "Steak": 12,
            "Rice": 29,
            "Chicken": 26,
            "Iceberg_Lettuce": 8,
            "Almonds": 2,
        },
        "calories": {
            "Steak": 167,
            "Rice": 275,
            "Chicken": 112,
            "Iceberg_Lettuce": 148,
            "Almonds": 286,
        },
    },
    "requirement": {
        "protein": 83,
        "carbs": 128,
        "calories": 1686,
    },
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.FOODS = pyo.Set(initialize=d["foods"])
    model.NUTRIENTS = pyo.Set(initialize=d["nutrients"])

    # Decision: servings of each food (non-negative, continuous; no availability cap).
    model.x = pyo.Var(model.FOODS, within=pyo.NonNegativeReals)

    # Objective: minimise total cost.
    def obj_rule(m):
        return sum(d["cost"][f] * m.x[f] for f in m.FOODS)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Each nutrient: total intake must be at least the requirement.
    def nutrient_rule(m, n):
        return sum(d["content"][n][f] * m.x[f] for f in m.FOODS) >= d["requirement"][n]

    model.nutrient = pyo.Constraint(model.NUTRIENTS, rule=nutrient_rule)

    return model


